nextflow_process {

    name "Test Process CIRI2"
    script "../main.nf"
    process "CIRI2"
    config "./nextflow.config"
    tag "modules"
    tag "modules_nfcore"
    tag "ciri2"

    test("homo_sapiens - bam - pairedend") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end: false ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.rna.paired_end.bam', checkIfExists: true)]
                input[1] = [
                    [ id:'fasta' ], file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)]
                input[2] = [ [:], []]
                input[3] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["log", "circrna", "error_log"])
                ).match() }
            )
        }
    }

    test("homo_sapiens - cram - pairedend") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end: false ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/cram/test.paired_end.sorted.cram', checkIfExists: true)
                ]
                input[1] = [
                    [ id:'fasta' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [ [:], [] ]
                input[3] = [ [:], [] ]
                """
            }
        }


        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(process.out, unstableKeys: ["log", "circrna", "error_log"])
                ).match() }
            )
        }
    }

